mapper.select:
SELECT u.UserID as id, u.registerTime, u.Username as name, u.Status as state, u.UserType as type,
       a.AthleteState as applyState, a.applyTime as applyTime
FROM user u
LEFT JOIN Athlete a ON u.UserID = a.UserID


        AND u.Username like CONCAT('%', #{listDto.name}, '%')


        AND u.UserType = #{listDto.type}


        AND u.registerTime > #{listDto.date}


ORDER BY u.registerTime
LIMIT #{listDto.pageSize} OFFSET #{listDto.currentPage}

SELECT COUNT(*)
FROM user


        AND Username like CONCAT('%', #{listDto.name}, '%')


        AND UserType = #{listDto.type}


        AND registerTime >= #{listDto.date}
